import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

public final class ClaimPaymentAllocator {

    public record Allocation(List<BigDecimal> amounts, BigDecimal remainder) {
    }

    private ClaimPaymentAllocator() {
    }

    public static List<BigDecimal> allocate(BigDecimal payment, List<BigDecimal> lineItems) {
        return allocateDetailed(payment, lineItems).amounts();
    }

    public static Allocation allocateDetailed(BigDecimal payment, List<BigDecimal> lineItems) {
        if (lineItems == null) {
            return new Allocation(List.of(), payment == null || payment.signum() <= 0 ? BigDecimal.ZERO : payment);
        }
        BigDecimal remaining = payment == null || payment.signum() <= 0 ? BigDecimal.ZERO : payment;
        List<BigDecimal> allocations = new ArrayList<>();
        for (BigDecimal item : lineItems) {
            BigDecimal owed = item == null || item.signum() <= 0 ? BigDecimal.ZERO : item;
            BigDecimal paid = remaining.min(owed);
            allocations.add(paid);
            remaining = remaining.subtract(paid);
        }
        return new Allocation(List.copyOf(allocations), remaining);
    }
}
